package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class HomerNamedDataTest {
    @TempDir Path root;
    @Test void fullNativeAuditPreservesRawCollapsedIdsMetadataAndPopulation()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Path work=root.resolve("work");var d=HomerNamedFixture.stage(o,work,runtime);HomerNamedFixture.output(work);assertEquals(1,HomerNamedData.audit(d,work,HomerNamedData.Limits.read(o),true));assertTrue(Files.readString(work.resolve("results.tsv")).contains("source-description"));assertTrue(Files.readString(work.resolve("resource-tss.tsv")).contains("NM_1.7-HOMER1"));assertTrue(Files.readString(work.resolve("native-tss-candidates.tsv")).contains("\"NM_1.7\""));assertTrue(Files.readString(work.resolve("native-category-populations.tsv")).contains("basic\tN\t0\t800"));assertTrue(Files.readString(work.resolve("peaks.tsv")).contains("pα"));}
    @Test void changedSourceAndMarkerInvalidateStaging()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);var d=HomerNamedFixture.stage(o,root.resolve("work"),runtime);d.verify();Files.writeString(Path.of(o.get("peaks")),"changed");assertThrows(IOException.class,d::verify);Files.writeString(runtime.home().resolve(HomerNamedRuntime.MARKER),"changed");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("other"),runtime));}
    @Test void duplicatePeaksAndUnknownStrandsRequireSeparatePolicies()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Path p=Path.of(o.get("peaks"));Files.writeString(p,"chr1\t104\t115\tsame\t1\t.\nchr1\t104\t115\tsame\t1\t+\n");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("dot"),runtime));o.put("peak-unknown-strand","original-plus");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("duplicate"),runtime));o.put("duplicate-ids","retain-ordinal");var d=HomerNamedFixture.stage(o,root.resolve("pass"),runtime);assertEquals(1,d.duplicateIds());assertEquals(1,d.plusAssigned());assertNotEquals(d.peaks().get(0).alias(),d.peaks().get(1).alias());}
    @Test void malformedExtraFieldsOutOfBoundsAndCapacityFailWithoutFiltering()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Path p=Path.of(o.get("peaks"));int i=0;for(String text:new String[]{"chr1\t104\t115\tx\t1\t+\textra\n","chr1\t104\t1001\tx\t1\t+\n","chr9\t104\t115\tx\t1\t+\n"}){Files.writeString(p,text);Path w=root.resolve("bad"+(i++));assertThrows(IOException.class,()->HomerNamedFixture.stage(o,w,runtime));}Files.writeString(p,"chr1\t104\t115\tx\t1\t+\n");o.put("maximum-resource-records","1");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("capacity"),runtime));}
    @Test void corruptedCoordinatesFeatureTssAndPopulationFailCompleteAudit()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Path w=root.resolve("work");var d=HomerNamedFixture.stage(o,w,runtime);for(String[] replacement:new String[][]{{"\t105\t115\t","\t106\t115\t"},{"\texon\trepeat\t","\twrong\trepeat\t"},{"\t10\tNM_1.7\t","\t11\tNM_1.7\t"},{"\t10\tNM_1.7\t","\t10\twrong\t"}}){HomerNamedFixture.output(w);Path p=w.resolve("original.stdout");Files.writeString(p,Files.readString(p).replace(replacement[0],replacement[1]));assertThrows(IOException.class,()->HomerNamedData.audit(d,w,HomerNamedData.Limits.read(o),true));}HomerNamedFixture.output(w);Path stats=w.resolve("original-annotation-stats.tsv");Files.writeString(stats,Files.readString(stats).replace("\t800\t","\t801\t"));assertThrows(IOException.class,()->HomerNamedData.audit(d,w,HomerNamedData.Limits.read(o),true));}
    @Test void incompleteRowsDuplicateRowsAndFailedHelperInvalidateExitZeroOutput()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Path w=root.resolve("work");var d=HomerNamedFixture.stage(o,w,runtime);HomerNamedFixture.output(w);Path p=w.resolve("original.stdout");String original=Files.readString(p);Files.writeString(p,original.substring(0,original.indexOf('\n')+1));assertThrows(IOException.class,()->HomerNamedData.audit(d,w,HomerNamedData.Limits.read(o),true));Files.writeString(p,original+original.substring(original.indexOf('\n')+1));assertThrows(IOException.class,()->HomerNamedData.audit(d,w,HomerNamedData.Limits.read(o),true));HomerNamedFixture.output(w);Files.writeString(w.resolve("original.stderr"),"helper not found\nDone annotating peaks file\n");assertThrows(IOException.class,()->HomerNamedData.audit(d,w,HomerNamedData.Limits.read(o),true));}
    @Test void missingTssAndOriginalBadResourceAnchorsNeedExplicitPolicies()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Files.writeString(Path.of(o.get("peaks")),"chr2\t104\t115\tx\t1\t+\n");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("missing"),runtime));o.put("missing-tss-contig","retain-NA");assertEquals(1,HomerNamedFixture.stage(o,root.resolve("retained"),runtime).missingTss());Files.writeString(runtime.genomeFile("mm10","mm10.tss"),"outside\tchr1\t0\t4000\t0\n");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("anchor"),runtime));o.put("tss-resource-anchors","retain-original");assertEquals(1,HomerNamedFixture.stage(o,root.resolve("original-anchor"),runtime).tss().outOfReferenceAnchors());}
    @Test void originalFeatureIrregularitiesAndGeometryTiesNeedIndependentChoices()throws Exception{var o=HomerNamedFixture.options(root);var runtime=HomerNamedFixture.runtime(root);Path a=runtime.genomeFile("mm10","mm10.basic.annotation");Files.writeString(a,"a\tchr1\t0\t1500000000\t+\tN\t1\nb\tchr1\t0\t1500000000\t+\tE\t2\n");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("bounds"),runtime));o.put("resource-bounds","retain-original");assertThrows(IOException.class,()->HomerNamedFixture.stage(o,root.resolve("ties"),runtime));o.put("feature-ties","retain-original");assertEquals(1,HomerNamedFixture.stage(o,root.resolve("retained"),runtime).featureTies());}
}
